-- =========================================================
-- Banco de estudos: e-commerce com dados fictícios
-- Gerado com apoio de IA para praticar SQL (PostgreSQL)
-- Modelo de tabelas baseado na Trilha SQL de Carlos Oliveira
-- Pode rodar quantas vezes quiser: o script apaga e recria tudo
-- =========================================================

DROP TABLE IF EXISTS avaliacoes, pagamentos, itens_pedido, pedidos, clientes, produtos, categorias CASCADE;

CREATE TABLE categorias (
    categoria_id  SERIAL PRIMARY KEY,
    nome          VARCHAR(100) NOT NULL,
    descricao     VARCHAR(255),
    ativo         BOOLEAN DEFAULT TRUE
);

CREATE TABLE produtos (
    produto_id    SERIAL PRIMARY KEY,
    categoria_id  INT REFERENCES categorias(categoria_id),
    nome          VARCHAR(150) NOT NULL,
    preco         DECIMAL(10,2) NOT NULL,
    estoque       INT DEFAULT 0,
    marca         VARCHAR(100),
    ativo         BOOLEAN DEFAULT TRUE
);

CREATE TABLE clientes (
    cliente_id    SERIAL PRIMARY KEY,
    nome          VARCHAR(150) NOT NULL,
    email         VARCHAR(150) UNIQUE,
    cpf           VARCHAR(14) UNIQUE,
    telefone      VARCHAR(20),
    cidade        VARCHAR(100),
    estado        CHAR(2),
    cep           VARCHAR(9),
    data_nascimento DATE,
    ativo         BOOLEAN DEFAULT TRUE,
    data_cadastro DATE
);

CREATE TABLE pedidos (
    pedido_id     SERIAL PRIMARY KEY,
    cliente_id    INT REFERENCES clientes(cliente_id),
    data_pedido   DATE NOT NULL,
    status        VARCHAR(20),
    valor_total   DECIMAL(10,2),
    frete         DECIMAL(10,2) DEFAULT 0,
    desconto      DECIMAL(10,2) DEFAULT 0,
    data_entrega_prevista  DATE,
    data_entrega_realizada DATE
);

CREATE TABLE itens_pedido (
    item_pedido_id SERIAL PRIMARY KEY,
    pedido_id      INT REFERENCES pedidos(pedido_id),
    produto_id     INT REFERENCES produtos(produto_id),
    quantidade     INT NOT NULL,
    preco_unitario DECIMAL(10,2) NOT NULL
);

CREATE TABLE pagamentos (
    pagamento_id   SERIAL PRIMARY KEY,
    pedido_id      INT REFERENCES pedidos(pedido_id),
    metodo         VARCHAR(30),
    status         VARCHAR(20),
    valor          DECIMAL(10,2),
    data_pagamento DATE
);

CREATE TABLE avaliacoes (
    avaliacao_id   SERIAL PRIMARY KEY,
    produto_id     INT REFERENCES produtos(produto_id),
    cliente_id     INT REFERENCES clientes(cliente_id),
    nota           INT CHECK (nota BETWEEN 1 AND 5),
    comentario     VARCHAR(255),
    data_avaliacao DATE
);


