-- Ajusta as sequências do SERIAL para os próximos INSERTs começarem do número certo
SELECT setval('categorias_categoria_id_seq',   (SELECT MAX(categoria_id)   FROM categorias));
SELECT setval('produtos_produto_id_seq',       (SELECT MAX(produto_id)     FROM produtos));
SELECT setval('clientes_cliente_id_seq',       (SELECT MAX(cliente_id)     FROM clientes));
SELECT setval('pedidos_pedido_id_seq',         (SELECT MAX(pedido_id)      FROM pedidos));
SELECT setval('itens_pedido_item_pedido_id_seq',(SELECT MAX(item_pedido_id) FROM itens_pedido));
SELECT setval('pagamentos_pagamento_id_seq',   (SELECT MAX(pagamento_id)   FROM pagamentos));
SELECT setval('avaliacoes_avaliacao_id_seq',   (SELECT MAX(avaliacao_id)   FROM avaliacoes));

-- Conferência rápida
SELECT 'categorias' AS tabela, COUNT(*) FROM categorias
UNION ALL SELECT 'produtos', COUNT(*) FROM produtos
UNION ALL SELECT 'clientes', COUNT(*) FROM clientes
UNION ALL SELECT 'pedidos', COUNT(*) FROM pedidos
UNION ALL SELECT 'itens_pedido', COUNT(*) FROM itens_pedido
UNION ALL SELECT 'pagamentos', COUNT(*) FROM pagamentos
UNION ALL SELECT 'avaliacoes', COUNT(*) FROM avaliacoes;
